//! Full-length frames (design harness v2 §2.1): the box is the document, `box_size`, the LWW extent and
//! document-height fields, and the codec compatibility with blobs written before them (fixtures in
//! `tests/fixtures/compat/`, generated by the build at `18f166f`, before the codec changed).
#![allow(
    clippy::unwrap_used,
    clippy::panic,
    clippy::float_cmp,
    reason = "test harness: failures are reported by panicking"
)]

use std::path::PathBuf;

use penwise_core::codec::edit::{
    EDIT_VERSION, EDIT_VERSION_V1, EDIT_VERSION_V4, decode_edit, encode_edit,
};
use penwise_core::codec::item::{ITEM_VERSION, decode_item, encode_item};
use penwise_core::edit::{Edit, EditError, ItemPatch, LassoParams, UndoStack, hit_test, lasso};
use penwise_core::item::{
    Affine, FrameExtent, FrameItem, FramePreset, FrameSpec, Item, ItemId, ItemKind, Layer,
    LayerSet, PageKind, Scene, VariantSpec, set_doc_height, set_extent, variant_frames,
};

fn id(n: u8) -> ItemId {
    ItemId([n; 16])
}

fn fixture(name: &str) -> Vec<u8> {
    let path = PathBuf::from(env!("CARGO_MANIFEST_DIR"))
        .join("tests/fixtures/compat")
        .join(name);
    std::fs::read(&path).unwrap_or_else(|e| panic!("fixture {name}: {e}"))
}

/// The variant frame the v3 / v4 fixtures were written from.
fn v3_variant_frame() -> Item {
    Item {
        id: id(7),
        layer: Layer::Ink,
        z: 3 << 16,
        transform: Affine::translate(530.0, 20.0),
        kind: ItemKind::Frame(FrameItem {
            project: "portfolio".to_owned(),
            route: "/about".to_owned(),
            preset: FramePreset::Phone,
            css_w: 390,
            css_h: 844,
            patch: Some(r#"{"css":"h1{color:red}","dom":[]}"#.to_owned()),
            label: "bigger hero".to_owned(),
            group: Some("grp-1".to_owned()),
            chosen: true,
            extent: FrameExtent::Viewport,
            doc_h: 0,
        }),
    }
}

fn v3_plain_frame() -> Item {
    Item {
        id: id(8),
        layer: Layer::Ink,
        z: 4 << 16,
        transform: Affine::translate(0.0, 0.0),
        kind: ItemKind::Frame(FrameItem {
            extent: FrameExtent::Viewport,
            ..FrameItem::new(
                "portfolio".to_owned(),
                "/".to_owned(),
                FramePreset::Desktop,
                1440,
                900,
            )
        }),
    }
}

fn full_frame(doc_h: u32) -> Item {
    let spec = FrameSpec::new(
        "portfolio".to_owned(),
        "/".to_owned(),
        FramePreset::Desktop,
        None,
        None,
        100.0,
        50.0,
    )
    .unwrap();
    let mut item = spec.item(id(1), Layer::Ink, 0);
    let ItemKind::Frame(frame) = &mut item.kind else {
        panic!("frame");
    };
    frame.doc_h = doc_h;
    item
}

fn frame_of(scene: &Scene, item: ItemId) -> &FrameItem {
    let Some(ItemKind::Frame(frame)) = scene.get(item).map(|i| &i.kind) else {
        panic!("frame expected");
    };
    frame
}

fn item_blob(item: &Item) -> Vec<u8> {
    let mut out = Vec::new();
    encode_item(item, &mut out);
    out
}

fn edit_blob(edit: &Edit) -> Vec<u8> {
    let mut out = Vec::new();
    encode_edit(edit, &mut out);
    out
}

#[test]
fn box_size_is_the_document_for_full_and_the_viewport_otherwise() {
    let mut frame = FrameItem::new(
        "p".to_owned(),
        "/".to_owned(),
        FramePreset::Desktop,
        1440,
        900,
    );
    assert_eq!(
        frame.extent,
        FrameExtent::Full,
        "new frames are full length"
    );
    assert_eq!(
        frame.box_size(None),
        [1440.0, 900.0],
        "unknown height: viewport"
    );
    frame.doc_h = 4000;
    assert_eq!(frame.box_size(None), [1440.0, 4000.0]);
    assert_eq!(
        frame.box_size(Some(6000.0)),
        [1440.0, 6000.0],
        "live height wins"
    );
    assert_eq!(
        frame.box_size(Some(300.0)),
        [1440.0, 900.0],
        "never below the viewport"
    );
    assert_eq!(
        frame.box_size(Some(f32::NAN)),
        [1440.0, 4000.0],
        "non-finite falls back to the hint"
    );
    assert_eq!(
        frame.box_size(Some(1.0e30)),
        [1440.0, 1_048_576.0],
        "a hostile live height is clamped to MAX_FRAME_SIDE"
    );
    frame.doc_h = u32::MAX;
    assert_eq!(
        frame.box_size(None)[1],
        1_048_576.0,
        "and so is a hostile hint"
    );
    frame.extent = FrameExtent::Viewport;
    assert_eq!(frame.box_size(Some(6000.0)), [1440.0, 900.0]);
    assert_eq!(
        frame.page_size(),
        [1440.0, 900.0],
        "page_size stays the viewport"
    );
}

#[test]
fn bounds_hit_and_lasso_use_the_synced_box() {
    let mut scene = Scene::new(PageKind::Infinite);
    scene.apply(&Edit::Add(full_frame(4000))).unwrap();
    let b = scene.bounds(id(1)).unwrap();
    assert_eq!(
        (b.min_x, b.min_y, b.max_x, b.max_y),
        (100.0, 50.0, 1540.0, 4050.0)
    );
    assert_eq!(
        hit_test(&scene, [500.0, 3000.0], 0.0, LayerSet::ALL),
        vec![id(1)]
    );
    assert!(hit_test(&scene, [500.0, 4100.0], 0.0, LayerSet::ALL).is_empty());
    let polygon = [
        [0.0, 3000.0],
        [2000.0, 3000.0],
        [2000.0, 3500.0],
        [0.0, 3500.0],
    ];
    assert_eq!(
        lasso(&scene, &polygon, LayerSet::ALL, &LassoParams::DEFAULT),
        Vec::<ItemId>::new(),
        "a lasso inside the box that does not enclose it selects nothing"
    );
    let around = [[0.0, 0.0], [2000.0, 0.0], [2000.0, 4200.0], [0.0, 4200.0]];
    assert_eq!(
        lasso(&scene, &around, LayerSet::ALL, &LassoParams::DEFAULT),
        vec![id(1)]
    );

    // The server writes a taller height: the index follows, so hits below the old box now land.
    let edits = set_doc_height(&scene, id(1), 9000).unwrap();
    scene.apply_all(&edits).unwrap();
    assert_eq!(
        hit_test(&scene, [500.0, 8000.0], 0.0, LayerSet::ALL),
        vec![id(1)]
    );
    // Back to a viewport frame: the box shrinks to the preset again.
    scene
        .apply_all(&set_extent(&scene, id(1), FrameExtent::Viewport))
        .unwrap();
    assert!(hit_test(&scene, [500.0, 8000.0], 0.0, LayerSet::ALL).is_empty());
    assert_eq!(scene.bounds(id(1)).unwrap().max_y, 950.0);
}

#[test]
fn doc_height_and_extent_edits_are_lww_fields_that_undo() {
    let mut scene = Scene::new(PageKind::Infinite);
    scene.apply(&Edit::Add(full_frame(0))).unwrap();
    assert!(
        set_doc_height(&scene, id(1), 0).unwrap().is_empty(),
        "unchanged: no edit"
    );
    assert!(set_extent(&scene, id(1), FrameExtent::Full).is_empty());
    assert!(
        set_doc_height(&scene, id(2), 5).unwrap().is_empty(),
        "unknown id"
    );
    assert_eq!(
        set_doc_height(&scene, id(1), (1 << 20) + 1),
        Err(EditError::InvalidValue {
            field: "frame_doc_h"
        })
    );

    let mut undo = UndoStack::new(8);
    let taller = set_doc_height(&scene, id(1), 2500).unwrap();
    undo.apply_local(&mut scene, &taller).unwrap();
    assert_eq!(frame_of(&scene, id(1)).doc_h, 2500);
    let undone = undo.undo(&scene);
    scene.apply_all(&undone).unwrap();
    assert_eq!(frame_of(&scene, id(1)).doc_h, 0);
    let redone = undo.redo(&scene);
    scene.apply_all(&redone).unwrap();
    assert_eq!(frame_of(&scene, id(1)).doc_h, 2500);

    // Fields not applicable to other kinds are rejected by the scene.
    let patch = ItemPatch {
        frame_doc_h: Some(1),
        ..ItemPatch::default()
    };
    assert!(patch.applied(&v3_plain_frame(), false).is_ok());
}

#[test]
fn variants_copy_the_base_extent() {
    for extent in [FrameExtent::Full, FrameExtent::Viewport] {
        let mut scene = Scene::new(PageKind::Infinite);
        let mut base = full_frame(3000);
        let ItemKind::Frame(frame) = &mut base.kind else {
            panic!("frame")
        };
        frame.extent = extent;
        scene.apply(&Edit::Add(base)).unwrap();
        let spec = VariantSpec {
            id: id(2),
            label: "A".to_owned(),
            patch: "{}".to_owned(),
        };
        let edits = variant_frames(&scene, id(1), &[spec], "g", 1 << 16).unwrap();
        scene.apply_all(&edits).unwrap();
        assert_eq!(frame_of(&scene, id(2)).extent, extent);
        assert_eq!(frame_of(&scene, id(2)).doc_h, 3000);
    }
}

#[test]
fn out_of_range_doc_height_is_invalid() {
    let mut item = full_frame((1 << 20) + 1);
    assert_eq!(
        item.validate(),
        Err(EditError::InvalidValue {
            field: "frame_doc_h"
        })
    );
    let ItemKind::Frame(frame) = &mut item.kind else {
        panic!("frame")
    };
    frame.doc_h = 1 << 20;
    frame.check().unwrap();
}

#[test]
fn item_v4_round_trips_extent_and_doc_height() {
    for item in [full_frame(0), full_frame(31_415), v3_variant_frame()] {
        let bytes = item_blob(&item);
        assert_eq!(bytes[4..6], ITEM_VERSION.to_le_bytes());
        assert_eq!(ITEM_VERSION, 4);
        assert_eq!(decode_item(&bytes).as_ref(), Ok(&item));
        assert_eq!(item_blob(&decode_item(&bytes).unwrap()), bytes, "canonical");
    }
}

#[test]
fn item_v3_fixtures_decode_as_viewport_frames() {
    for (name, expected) in [
        ("item_v3_variant_frame.bin", v3_variant_frame()),
        ("item_v3_plain_frame.bin", v3_plain_frame()),
    ] {
        let bytes = fixture(name);
        assert_eq!(bytes[4..6], 3_u16.to_le_bytes(), "{name} is a v3 blob");
        let decoded = decode_item(&bytes).unwrap();
        assert_eq!(decoded, expected, "{name}");
        let ItemKind::Frame(frame) = &decoded.kind else {
            panic!("frame")
        };
        assert_eq!((frame.extent, frame.doc_h), (FrameExtent::Viewport, 0));
    }
}

#[test]
fn edit_v4_and_v1_fixtures_decode_and_re_encode_byte_for_byte() {
    let add_variant = Edit::Add(v3_variant_frame());
    let bytes = fixture("edit_v4_add_variant_frame.bin");
    assert_eq!(bytes[4..6], EDIT_VERSION_V4.to_le_bytes());
    assert_eq!(decode_edit(&bytes).as_ref(), Ok(&add_variant));
    assert_eq!(
        edit_blob(&add_variant),
        bytes,
        "a viewport variant frame still needs only v4"
    );

    let add_plain = Edit::Add(v3_plain_frame());
    let bytes = fixture("edit_v1_add_plain_frame.bin");
    assert_eq!(bytes[4..6], EDIT_VERSION_V1.to_le_bytes());
    assert_eq!(decode_edit(&bytes).as_ref(), Ok(&add_plain));
    assert_eq!(
        edit_blob(&add_plain),
        bytes,
        "a plain viewport frame stays v1"
    );

    let chosen = Edit::Update {
        id: id(7),
        patch: ItemPatch {
            frame_chosen: Some(false),
            frame_label: Some("v2".to_owned()),
            ..ItemPatch::default()
        },
    };
    let bytes = fixture("edit_v4_update_chosen_label.bin");
    assert_eq!(decode_edit(&bytes).as_ref(), Ok(&chosen));
    assert_eq!(edit_blob(&chosen), bytes);

    let group = Edit::Update {
        id: id(7),
        patch: ItemPatch {
            frame_patch: Some(None),
            frame_group: Some(Some("g".to_owned())),
            ..ItemPatch::default()
        },
    };
    let bytes = fixture("edit_v4_update_patch_group.bin");
    assert_eq!(decode_edit(&bytes).as_ref(), Ok(&group));
    assert_eq!(edit_blob(&group), bytes);
}

#[test]
fn edit_v5_carries_full_frames_and_the_new_fields() {
    let add = Edit::Add(full_frame(1234));
    let bytes = edit_blob(&add);
    assert_eq!(bytes[4..6], EDIT_VERSION.to_le_bytes());
    assert_eq!(EDIT_VERSION, 5);
    assert_eq!(decode_edit(&bytes).as_ref(), Ok(&add));
    assert_eq!(edit_blob(&decode_edit(&bytes).unwrap()), bytes, "canonical");

    let update = Edit::Update {
        id: id(1),
        patch: ItemPatch {
            frame_extent: Some(FrameExtent::Full),
            frame_doc_h: Some(18_000),
            ..ItemPatch::default()
        },
    };
    let bytes = edit_blob(&update);
    assert_eq!(bytes[4..6], EDIT_VERSION.to_le_bytes());
    assert_eq!(decode_edit(&bytes).as_ref(), Ok(&update));
}
